function ServicesCarousel() {
  const railRef = useRef<HTMLDivElement>(null);
  const programmaticScroll = useRef(false);
  const [active, setActive] = useState(0);
  const [paused, setPaused] = useState(false);
  const [reducedMotion, setReducedMotion] = useState(false);
  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReducedMotion(query.matches);
    update(); query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);
  useEffect(() => {
    if (paused || reducedMotion) return;
    const timer = window.setInterval(() => setActive((current) => (current + 1) % services.length), 3000);
    return () => window.clearInterval(timer);
  }, [paused, reducedMotion]);
  useEffect(() => {
    const rail = railRef.current;
    const card = rail?.children[active] as HTMLElement | undefined;
    if (!rail || !card) return;
    programmaticScroll.current = true;
    rail.scrollTo({ left: card.offsetLeft - rail.offsetLeft, behavior: reducedMotion ? "auto" : "smooth" });
    const release = window.setTimeout(() => { programmaticScroll.current = false; }, reducedMotion ? 80 : 650);
    return () => window.clearTimeout(release);
  }, [active, reducedMotion]);
  const syncActive = () => {
    const rail = railRef.current;
    if (!rail || programmaticScroll.current) return;
    const cards = Array.from(rail.children) as HTMLElement[];
    const nearest = cards.reduce((best, card, index) => Math.abs(card.offsetLeft - rail.scrollLeft) < Math.abs(cards[best].offsetLeft - rail.scrollLeft) ? index : best, 0);
    setActive(nearest);
  };
  const step = (direction: number) => setActive((current) => (current + direction + services.length) % services.length);
  return <section className="service-section service-carousel" aria-label="Willers Solutions services"><div className="section-heading service-carousel-heading"><div><Eyebrow>02 / OUR EXPERTISE</Eyebrow><h2>What we do,<br /><em>with intent.</em></h2></div><div className="carousel-controls service-carousel-controls"><button type="button" onClick={() => step(-1)} aria-label="Previous service"><ArrowLeft size={17} /></button><button type="button" onClick={() => step(1)} aria-label="Next service"><ArrowRight size={17} /></button><button type="button" className="carousel-pause" onClick={() => setPaused((value) => !value)} aria-pressed={paused} aria-label={paused ? "Resume automatic services carousel" : "Pause automatic services carousel"}>{paused ? <Play size={14} /> : <Pause size={14} />}<span>{paused ? "Play" : "Pause"}</span></button></div></div><div className="service-carousel-viewport" onPointerEnter={() => setPaused(true)} onPointerLeave={() => setPaused(false)} onFocusCapture={() => setPaused(true)} onBlurCapture={() => setPaused(false)}><div className="service-carousel-rail" ref={railRef} onScroll={syncActive}>{services.map((service, index) => <article className={`service-card ${active === index ? "is-current" : ""}`} key={service.number} tabIndex={0} onFocus={() => setActive(index)}><Link href={service.href} className="service-card-link" aria-label={`Read more about ${service.title}`}><div className="service-image"><img src={service.image} alt="" /></div><div className="service-meta"><span>{service.number}</span><h3>{service.title}</h3><p>{service.copy}</p><ArrowDownRight size={23} /></div></Link></article>)}</div></div><div className="mobile-swipe-hint service-swipe-hint" aria-hidden="true"><span className="mobile-swipe-rule" /><ArrowLeft size={14} /><span>Swipe to explore</span><ArrowRight size={14} /><span className="mobile-swipe-rule" /></div><div className="carousel-progress service-carousel-progress" aria-label={`Showing service ${active + 1} of ${services.length}`}>{services.map((service, index) => <button type="button" key={service.number} className={active === index ? "active" : ""} onClick={() => setActive(index)} aria-label={`Show ${service.title}`} aria-current={active === index ? "true" : undefined}><span /></button>)}</div></section>;
}
